#!/usr/bin/env python3
"""Exact builtin kernel axiom inventory; not a complete source or full gate."""
import json
from pathlib import Path
import re
import sys
PINS = {'Solidity.Backend.InternalFlow.LoopCallerPrefix.condition_run': ['Classical.choice', 'Quot.sound', 'propext'], 'Solidity.Backend.InternalFlow.LoopCallerPrefix.captured': ['Classical.choice', 'Quot.sound', 'propext'], 'Solidity.Backend.InternalFlow.LoopCallerPrefix.represented': ['Classical.choice', 'Quot.sound', 'propext'], 'Solidity.Backend.InternalFlow.LoopTargetChecks.CallerPrefixes.first_scoped': ['Classical.choice', 'Quot.sound', 'propext'], 'Solidity.Backend.InternalFlow.LoopTargetChecks.CallerPrefixes.second_scoped': ['Classical.choice', 'Quot.sound', 'propext'], 'Solidity.Backend.InternalFlow.LoopTargetChecks.CallerPrefixes.source_one': ['Classical.choice', 'Quot.sound', 'propext'], 'Solidity.Backend.InternalFlow.LoopTargetChecks.CallerPrefixes.source_two': ['Classical.choice', 'Quot.sound', 'propext'], 'Solidity.Backend.InternalFlow.LoopTargetChecks.CallerPrefixes.source_stopped': ['Classical.choice', 'Quot.sound', 'propext'], 'Solidity.Backend.InternalFlow.LoopTargetChecks.CallerPrefixes.source_captured': ['Classical.choice', 'Quot.sound', 'propext'], 'Solidity.Backend.InternalFlow.LoopTargetChecks.CallerPrefixes.body_cost': ['Classical.choice', 'Quot.sound', 'propext'], 'Solidity.Backend.InternalFlow.LoopTargetChecks.CallerPrefixes.body_code': ['Classical.choice', 'Quot.sound', 'propext'], 'Solidity.Backend.InternalFlow.LoopTargetChecks.CallerPrefixes.body_need': ['Classical.choice', 'Quot.sound', 'propext'], 'Solidity.Backend.InternalFlow.LoopTargetChecks.CallerPrefixes.body_frag': ['Classical.choice', 'Quot.sound', 'propext'], 'Solidity.Backend.InternalFlow.LoopTargetChecks.CallerPrefixes.first_reached': ['Classical.choice', 'Quot.sound', 'propext'], 'Solidity.Backend.InternalFlow.LoopTargetChecks.CallerPrefixes.second_reached': ['Classical.choice', 'Quot.sound', 'propext'], 'Solidity.Backend.InternalFlow.LoopTargetChecks.CallerPrefixes.reached_all': ['Classical.choice', 'Quot.sound', 'propext'], 'Solidity.Backend.InternalFlow.LoopTargetChecks.CallerPrefixes.protected_all': ['Classical.choice', 'Quot.sound', 'propext'], 'Solidity.Backend.InternalFlow.LoopCallerPrefix.condition_revert': ['Classical.choice', 'Quot.sound', 'propext'], 'Solidity.Backend.InternalFlow.LoopCallerPrefix.program_revert': ['Classical.choice', 'Quot.sound', 'propext']}
NAMES = ['Solidity.Backend.InternalFlow.LoopCallerPrefix.condition_run', 'Solidity.Backend.InternalFlow.LoopCallerPrefix.captured', 'Solidity.Backend.InternalFlow.LoopCallerPrefix.represented', 'Solidity.Backend.InternalFlow.LoopTargetChecks.CallerPrefixes.first_scoped', 'Solidity.Backend.InternalFlow.LoopTargetChecks.CallerPrefixes.second_scoped', 'Solidity.Backend.InternalFlow.LoopTargetChecks.CallerPrefixes.source_one', 'Solidity.Backend.InternalFlow.LoopTargetChecks.CallerPrefixes.source_two', 'Solidity.Backend.InternalFlow.LoopTargetChecks.CallerPrefixes.source_stopped', 'Solidity.Backend.InternalFlow.LoopTargetChecks.CallerPrefixes.source_captured', 'Solidity.Backend.InternalFlow.LoopTargetChecks.CallerPrefixes.body_cost', 'Solidity.Backend.InternalFlow.LoopTargetChecks.CallerPrefixes.body_code', 'Solidity.Backend.InternalFlow.LoopTargetChecks.CallerPrefixes.body_need', 'Solidity.Backend.InternalFlow.LoopTargetChecks.CallerPrefixes.body_frag', 'Solidity.Backend.InternalFlow.LoopTargetChecks.CallerPrefixes.first_reached', 'Solidity.Backend.InternalFlow.LoopTargetChecks.CallerPrefixes.second_reached', 'Solidity.Backend.InternalFlow.LoopTargetChecks.CallerPrefixes.reached_all', 'Solidity.Backend.InternalFlow.LoopTargetChecks.CallerPrefixes.protected_all', 'Solidity.Backend.InternalFlow.LoopCallerPrefix.condition_revert', 'Solidity.Backend.InternalFlow.LoopCallerPrefix.program_revert']
def check(text):
    if re.search(r"(?:^|\n).*?(?:error:|error\(|sorryAx)",text):
        raise ValueError("Lean diagnostic or untrusted axiom")
    rows = [(n,sorted(x.strip()for x in a.split(',')if x.strip()))
        for n,a in re.findall(r"'([^']+)' (?:depends on axioms:\s*\[([^\]]*)\]|does not depend on any axioms)",text)]
    if rows != [(n,PINS[n])for n in NAMES]:
        raise ValueError("missing, extra, duplicate, reordered or changed axiom report")
    return len(rows)
log = Path(sys.argv[1]).read_text()
print(json.dumps({'status':'pass','reports':check(log)}))
